#!/usr/bin/env bash
# K-VPN Node Deployer: offline-capable single-file source bundle.
# Review source before executing under root.
set -Eeuo pipefail
umask 077
for binary in base64 tar awk tail mktemp; do
  command -v "$binary" >/dev/null || { echo "Missing unpacking utility: $binary" >&2; exit 1; }
done
tmp=$(mktemp -d)
trap 'rm -rf -- "$tmp"' EXIT
payload_line=$(awk '/^__KVPN_INSTALL_PAYLOAD_BELOW__$/{print NR+1;exit}' "$0")
[[ -n "$payload_line" ]] || { echo 'Missing installer payload' >&2; exit 1; }
tail -n "+$payload_line" "$0" | base64 -d | tar -x -C "$tmp"
"$tmp/kvpn-node-deployer/install.sh" "$@"
exit $?
__KVPN_INSTALL_PAYLOAD_BELOW__
